// Expo config plugin — ship only the CPU architectures real phones use.
//
// A default Expo build packages native libraries for all four Android ABIs.
// Two of them, x86 and x86_64, are emulators and a handful of Chromebooks;
// no phone in a Ghanaian school is running one. They were 29 MB of a 62 MB
// download, and this app is handed out over WhatsApp and memory sticks, on
// connections where that difference is felt.
//
// This has to be a plugin rather than an edit to android/app/build.gradle:
// that file is regenerated by `expo prebuild`, which would throw a hand edit
// away. Plugins are re-applied on every prebuild, which is the point.
const { withAppBuildGradle } = require('@expo/config-plugins');

const DEFAULT_ABIS = ['armeabi-v7a', 'arm64-v8a'];

module.exports = function withAbiFilters(config, { abis = DEFAULT_ABIS } = {}) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('with-abi-filters: expected a Groovy build.gradle; the template changed.');
    }
    if (cfg.modResults.contents.includes('abiFilters')) return cfg;   // already applied

    const list = abis.map((a) => `'${a}'`).join(', ');
    const block = `    defaultConfig {\n        ndk {\n            abiFilters ${list}\n        }`;
    const next = cfg.modResults.contents.replace(/^\s*defaultConfig\s*\{/m, block);
    if (next === cfg.modResults.contents) {
      throw new Error('with-abi-filters: no defaultConfig block found in app/build.gradle.');
    }
    cfg.modResults.contents = next;
    return cfg;
  });
};
